import React, { useState } from 'react';
import './App.css';

// High Quality Reliable Unsplash Images for Photography Website
const galleryImages = [
  { id: 1, title: 'Wedding Ceremony', category: 'Weddings', url: 'https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=80' },
  { id: 2, title: 'Nature & Landscape', category: 'Nature', url: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80' },
  { id: 3, title: 'Portrait Session', category: 'Portraits', url: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=800&q=80' },
  { id: 4, title: 'Birthday Celebration', category: 'Events', url: 'https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=800&q=80' },
  { id: 5, title: 'Bridal Portrait', category: 'Weddings', url: 'https://images.unsplash.com/photo-1511285560929-80b456fea0bc?auto=format&fit=crop&w=800&q=80' },
  { id: 6, title: 'Mountain Sunset', category: 'Nature', url: 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80' }
];

const services = [
  { title: 'Wedding Photography', desc: 'Capturing your special moments with elegance and timeless storytelling.' },
  { title: 'Event Coverage', desc: 'Professional coverage for corporate events, birthdays, and anniversaries.' },
  { title: 'Portrait & Outdoor Sessions', desc: 'High-end portraits in natural light and studio environments.' }
];

const packages = [
  { title: 'Basic Package', price: '$299', features: ['3 Hours Coverage', '50 Edited Photos', 'Online Gallery'] },
  { title: 'Standard Package', price: '$599', features: ['6 Hours Coverage', '150 Edited Photos', 'Album & USB Drive'] },
  { title: 'Premium Package', price: '$999', features: ['Full Day Coverage', 'Unlimited Edited Photos', 'Drone Shots & Luxury Album'] }
];

const reviews = [
  { name: 'Ayesha Khan', text: 'Absolutely amazing photography! Captured every emotion perfectly at our wedding.' },
  { name: 'Hamza Ali', text: 'Professional, punctual, and high quality photos. Highly recommended!' },
  { name: 'Sara Ahmed', text: 'Loved the portrait session. The colors and editing were stunning.' }
];

function App() {
  const [showLogin, setShowLogin] = useState(false);
  const [favorites, setFavorites] = useState([]);
  const [booking, setBooking] = useState({ name: '', email: '', date: '', package: 'Standard Package' });

  const toggleFavorite = (id) => {
    if (favorites.includes(id)) {
      setFavorites(favorites.filter(favId => favId !== id));
    } else {
      setFavorites([...favorites, id]);
    }
  };

  const handleBookingSubmit = (e) => {
    e.preventDefault();
    alert(`Thank you ${booking.name}! Your booking request for ${booking.date} has been submitted.`);
    setBooking({ name: '', email: '', date: '', package: 'Standard Package' });
  };

  return (
    <div className="app-container">
      {/* Navigation */}
      <nav className="navbar">
        <div className="logo">CaptureStudio</div>
        <ul className="nav-links">
          <li><a href="#hero">Home</a></li>
          <li><a href="#gallery">Gallery</a></li>
          <li><a href="#services">Services</a></li>
          <li><a href="#packages">Packages</a></li>
          <li><a href="#about">About</a></li>
          <li><a href="#favorites">Favorites ({favorites.length})</a></li>
          <li><a href="#booking">Booking</a></li>
        </ul>
        <button className="btn-login" onClick={() => setShowLogin(true)}>Login</button>
      </nav>

      {/* Hero Section */}
      <section id="hero" className="hero-section">
        <div className="hero-overlay">
          <h1>Capturing Timeless Stories</h1>
          <p>Professional photography in Pakistan for Weddings, Birthdays, Portraits & Nature.</p>
          <a href="#booking" className="btn-primary">Book Your Session Now</a>
        </div>
      </section>

      {/* Gallery Section */}
      <section id="gallery" className="section">
        <h2>Our Gallery</h2>
        <div className="gallery-grid">
          {galleryImages.map(img => (
            <div key={img.id} className="gallery-card">
              <img src={img.url} alt={img.title} />
              <div className="gallery-info">
                <span>{img.title}</span>
                <button 
                  className={`btn-heart ${favorites.includes(img.id) ? 'active' : ''}`}
                  onClick={() => toggleFavorite(img.id)}
                >
                  ♥
                </button>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Services Section */}
      <section id="services" className="section bg-light">
        <h2>Services</h2>
        <div className="services-grid">
          {services.map((s, index) => (
            <div key={index} className="card">
              <h3>{s.title}</h3>
              <p>{s.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* Packages Section */}
      <section id="packages" className="section">
        <h2>Packages</h2>
        <div className="packages-grid">
          {packages.map((pkg, index) => (
            <div key={index} className="package-card">
              <h3>{pkg.title}</h3>
              <div className="price">{pkg.price}</div>
              <ul>
                {pkg.features.map((feat, idx) => (
                  <li key={idx}>{feat}</li>
                ))}
              </ul>
              <a href="#booking" className="btn-secondary">Choose Plan</a>
            </div>
          ))}
        </div>
      </section>

      {/* About Section & Reviews */}
      <section id="about" className="section bg-light">
        <h2>About Us</h2>
        <div className="about-container">
          <div className="about-image">
            <img src="https://images.unsplash.com/photo-1554048612-b6a482bc67e5?auto=format&fit=crop&w=800&q=80" alt="Photographer at work" />
          </div>
          <div className="about-content">
            <h3>Crafting Visual Art with Passion</h3>
            <p>
              We are a team of professional photographers dedicated to capturing the raw beauty, emotion, and moments of your lives. With over 8 years of industry experience, we specialize in high-definition wedding photography, portrait art, and nature compositions.
            </p>
          </div>
        </div>

        {/* Reviews */}
        <div className="reviews-container">
          <h3>Client Reviews</h3>
          <div className="reviews-grid">
            {reviews.map((rev, index) => (
              <div key={index} className="review-card">
                <p>"{rev.text}"</p>
                <h4>- {rev.name}</h4>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Favorites Section */}
      <section id="favorites" className="section">
        <h2>Your Favorites</h2>
        {favorites.length === 0 ? (
          <p className="no-favs">No favorite photos added yet. Click the heart icon on any gallery photo!</p>
        ) : (
          <div className="gallery-grid">
            {galleryImages.filter(img => favorites.includes(img.id)).map(img => (
              <div key={img.id} className="gallery-card">
                <img src={img.url} alt={img.title} />
                <div className="gallery-info">
                  <span>{img.title}</span>
                  <button className="btn-heart active" onClick={() => toggleFavorite(img.id)}>♥</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {/* Compact Booking Section */}
      <section id="booking" className="section bg-light">
        <h2>Book a Session</h2>
        <div className="booking-card">
          <form onSubmit={handleBookingSubmit} className="booking-form">
            <div className="form-group">
              <label>Full Name</label>
              <input 
                type="text" 
                required 
                value={booking.name} 
                onChange={(e) => setBooking({...booking, name: e.target.value})}
                placeholder="Enter your name" 
              />
            </div>
            <div className="form-group">
              <label>Email Address</label>
              <input 
                type="email" 
                required 
                value={booking.email} 
                onChange={(e) => setBooking({...booking, email: e.target.value})}
                placeholder="Enter your email" 
              />
            </div>
            <div className="form-group">
              <label>Event Date</label>
              <input 
                type="date" 
                required 
                value={booking.date} 
                onChange={(e) => setBooking({...booking, date: e.target.value})}
              />
            </div>
            <div className="form-group">
              <label>Select Package</label>
              <select 
                value={booking.package} 
                onChange={(e) => setBooking({...booking, package: e.target.value})}
              >
                <option>Basic Package</option>
                <option>Standard Package</option>
                <option>Premium Package</option>
              </select>
            </div>
            <button type="submit" className="btn-primary btn-full">Submit Booking</button>
          </form>
        </div>
      </section>

      {/* Footer with Circular Social Media Icons */}
      <footer className="footer">
        <p>&copy; 2026 CaptureStudio. All rights reserved.</p>
        <div className="social-icons">
          <a href="https://instagram.com" target="_blank" rel="noreferrer" className="social-btn instagram" title="Instagram">
            <i className="fab fa-instagram"></i>
          </a>
          <a href="https://wa.me/" target="_blank" rel="noreferrer" className="social-btn whatsapp" title="WhatsApp">
            <i className="fab fa-whatsapp"></i>
          </a>
          <a href="https://tiktok.com" target="_blank" rel="noreferrer" className="social-btn tiktok" title="TikTok">
            <i className="fab fa-tiktok"></i>
          </a>
        </div>
      </footer>

      {/* Login Modal with Close (X) Button */}
      {showLogin && (
        <div className="modal-backdrop" onClick={() => setShowLogin(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close" onClick={() => setShowLogin(false)}>&times;</button>
            <h3>Account Login</h3>
            <form onSubmit={(e) => { e.preventDefault(); setShowLogin(false); }}>
              <div className="form-group">
                <label>Email</label>
                <input type="email" placeholder="Email" required />
              </div>
              <div className="form-group">
                <label>Password</label>
                <input type="password" placeholder="Password" required />
              </div>
              <button type="submit" className="btn-primary btn-full">Login</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
